import{_ as d,o as t,c as o,a2 as a}from"./chunks/framework.Dsf4_p3t.js";const u=JSON.parse('{"title":"渲染管线","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/rendering.md","filePath":"zh/guide/rendering.md","lastUpdated":1791110416000}'),r={name:"zh/guide/rendering.md"};function i(c,e,n,l,h,s){return t(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="渲染管线" tabindex="-1">渲染管线 <a class="header-anchor" href="#渲染管线" aria-label="Permalink to &quot;渲染管线&quot;">​</a></h1><h2 id="两层架构" tabindex="-1">两层架构 <a class="header-anchor" href="#两层架构" aria-label="Permalink to &quot;两层架构&quot;">​</a></h2><ul><li><strong>Application 层</strong>：构建 Widget 树，Taitank 计算布局，录制 RenderCommand 到 RenderContext</li><li><strong>Render 层</strong>：从 SPSC 环形队列消费命令，tgfx 执行绘制</li></ul><h2 id="渲染命令" tabindex="-1">渲染命令 <a class="header-anchor" href="#渲染命令" aria-label="Permalink to &quot;渲染命令&quot;">​</a></h2><p>RenderCommand 支持以下类型：</p><ul><li><code>kBeginFrame</code> / <code>kEndFrame</code>：帧边界</li><li><code>kDrawRect</code>：绘制矩形</li><li><code>kDrawRoundedRect</code>：绘制圆角矩形</li><li><code>kDrawText</code>：绘制文本（UTF-8）</li><li><code>kClipRect</code>：设置裁剪区域</li><li><code>kTranslate</code>：平移变换</li><li><code>kSave</code> / <code>kRestore</code>：保存/恢复渲染状态</li></ul><h2 id="桌面端" tabindex="-1">桌面端 <a class="header-anchor" href="#桌面端" aria-label="Permalink to &quot;桌面端&quot;">​</a></h2><p>桌面与移动端是同一个形态：tgfx <code>Window</code> 持有 GPU 上下文与交换链， <code>Surface::MakeFrom(context, window)</code> 逐帧获取表面，<code>context-&gt;submit()</code> 提交并呈现。 只有窗口<strong>创建</strong>是平台相关的：</p><table tabindex="0"><thead><tr><th>后端</th><th>tgfx Window</th><th>原生句柄来源</th></tr></thead><tbody><tr><td><code>TGFX_USE_OPENGL</code>（Linux）</td><td><code>tgfx::EGLWindow::MakeFrom(XID)</code></td><td><code>glfwGetX11Window()</code></td></tr><tr><td><code>TGFX_USE_OPENGL</code>（Windows）</td><td><code>tgfx::WGLWindow::MakeFrom(HWND)</code></td><td><code>glfwGetWin32Window()</code></td></tr><tr><td><code>TGFX_USE_METAL</code>（Apple）</td><td><code>tgfx::MetalWindow::MakeFrom(CAMetalLayer*)</code></td><td>GLFW NSWindow 的 content view</td></tr><tr><td><code>TGFX_USE_VULKAN</code>（Windows）</td><td><code>tgfx::VulkanWindow::MakeFrom(HWND)</code></td><td><code>glfwGetWin32Window()</code></td></tr><tr><td><code>TGFX_USE_D3D12</code>（Windows）</td><td><code>tgfx::D3D12Window::MakeForHwnd(HWND)</code></td><td><code>glfwGetWin32Window()</code></td></tr></tbody></table><p>GLFW 窗口以 <code>GLFW_NO_API</code> 创建；任何平台 NeoFlux 都不自管 GL/EGL/WGL 上下文。 tgfx 背后没有内置光栅器——tgfx 是唯一的渲染实现。</p><h2 id="移动端" tabindex="-1">移动端 <a class="header-anchor" href="#移动端" aria-label="Permalink to &quot;移动端&quot;">​</a></h2><p>tgfx 直接渲染到平台提供的 Surface：</p><ul><li>Android：<code>tgfx::EGLWindow::MakeFrom(ANativeWindow*)</code></li><li>iOS：<code>tgfx::EAGLWindow::MakeFrom(CAEAGLLayer*)</code>（需要 ObjC++ 应用壳，尚未接线）</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="./architecture">架构</a></li><li><a href="./cross-platform">跨平台</a></li></ul>',15)])])}const g=d(r,[["render",i]]);export{u as __pageData,g as default};
